import{_ as a,o as r,c as o,a6 as i}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"跨境电商出图与本地化","description":"","frontmatter":{"id":"cross-border","title":"跨境电商出图与本地化","chapter":"03","status":"已公开","evidence_status":"方法已整理，未执行图像任务","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills"],"order":23},"headers":[],"relativePath":"ecommerce/cross-border.md","filePath":"ecommerce/cross-border.md"}'),t={name:"ecommerce/cross-border.md"};function l(s,e,c,d,n,h){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="跨境电商出图与本地化" tabindex="-1">跨境电商出图与本地化 <a class="header-anchor" href="#跨境电商出图与本地化" aria-label="Permalink to &quot;跨境电商出图与本地化&quot;">​</a></h1><p>先确定市场、站点、位置与模块，再确定语言、比例和文件。Amazon主图、商品副图、A+，Shopify主题的商品媒体与横幅，Shopee各市场入口承担不同任务。平台规则集中在<a href="/ai-visual-creation-handbook/resources/">资料库</a>，具体数值以当前官方页面、登录后的模块提示和实际预览为准。</p><h2 id="跨境制作顺序" tabindex="-1">跨境制作顺序 <a class="header-anchor" href="#跨境制作顺序" aria-label="Permalink to &quot;跨境制作顺序&quot;">​</a></h2><ol><li>建“渠道×市场×图片位置×SKU”清单。每行保存当前要求的出处与核对时间。</li><li>固定商品身份和发货内容；场景可以本地化，商品尺寸、结构与功能不能随市场改变。</li><li>根据真实数据转换单位，保留计算依据。标题、标签、警示和包装文字分别处理，不直接让整图模型改所有小字。</li><li>让目标语言复核者检查自然表达、数值、使用说明及当地语境。缺依据的合规或认证声明留空待补。</li><li>先做一种语言的母版和一张样图，检查后按SKU扩展；不同位置单独排版裁切，不只缩放同一张长图。</li><li>在实际商品页／编辑器预览桌面与手机，查看首屏裁切、文字可读性和图片顺序。</li></ol><h2 id="最小交付清单" tabindex="-1">最小交付清单 <a class="header-anchor" href="#最小交付清单" aria-label="Permalink to &quot;最小交付清单&quot;">​</a></h2><p>文件命名含市场、语言、SKU、位置和版本；配套事实表、文案对照、规格来源、检查结果和可编辑文件说明。广告图和商品主图分别制作，避免把宣传字样误放到不允许的位置。</p><p>这页提供流程方法，尚未在Amazon、Shopify或Shopee后台完成真实上传。首批跨境实操案例列入待补清单，平台变化只修订受影响步骤。</p><h2 id="借鉴业务skill时怎么核对" tabindex="-1">借鉴业务Skill时怎么核对 <a class="header-anchor" href="#借鉴业务skill时怎么核对" aria-label="Permalink to &quot;借鉴业务Skill时怎么核对&quot;">​</a></h2><p>新收录的电商Skill库有跨境本地化与检查脚本，可借鉴市场、语言、尺寸与变体的任务拆分。来源中的区域偏好、尺码对照和平台规格不能直接成为本库规则；先用真实商品参数和当前站点资料复核。准确文字优先独立排版。</p><p>脚本入口实际位于shared/scripts或技能目录的scripts下。先核对工作目录、素材相对路径与后端，再试一项任务；本项目尚未运行其生成任务。</p>',10)])])}const _=a(t,[["render",l]]);export{m as __pageData,_ as default};
